entries[30547] = { ["name"] = "Elementare Zephyriumladung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nElementarsprengpulver (2), Teufelseisengehäuse , Eine Handvoll Teufelseisenbolzen\nVerkäufer:\nKaraaz\nZone:\nNethersturm\nDas Konsortium - Respektvoll\nKosten:\n8\n\nVerkäufer:\nPaulsta'ats\nZone:\nNagrand\nDas Konsortium - Respektvoll\nKosten:\n8\n\n(2)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf.\nBenötigt Ingenieurskunst der Scherbenwelt\n(50)" }
entries[30548] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse (2), Eine Handvoll Teufelseisenbolzen (2), Urleben (4), Empfindlicher Arkanitwandler\nQuest:\nDer schockdrosselnde Partikelextraktor!\nZone:\nZangarmarschen\n\nQuest:\nDer schockdrosselnde Partikelextraktor!\nZone:\nZangarmarschen\n\nEinzigartig\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke.\nZeigt die Position aller nahen Gaswolken auf der Minikarte an, solang sich der Partikelextraktor in Eurem Inventar befindet.\nBenötigt Ingenieurskunst der Scherbenwelt\n(5)" }
