entries[31230] = { ["name"] = "Von der Schippe springen", ["text"] = "Tödliche Angriffe setzen Eure Gesundheit auf 7% Eurer maximalen Gesundheit, statt Euch zu töten. Danach wird Euer erlittener Schaden 3 Sek. lang um 85% verringert. Dieser Effekt kann nur einmal alle 6 Min. auftreten." }
entries[31231] = { ["name"] = "Von der Schippe springen", ["text"] = "Sofort\nIhr verfügt über eine Chance, einer Schaden zufügenden Attacke vollständig zu widerstehen, die Euch ansonsten töten würde, und reduziert sämtlichen erlittenen Schaden 3 Sek. lang um 85%. Dieser Effekt kann nicht öfter als einmal pro Minute auftreten." }
