entries[31765] = { ["name"] = "Blitzschlagschild", ["text"] = "190 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% haben, Nahkampf- oder Distanzangreifer zu treffen und 2 Schaden zu verursachen. Jedes Mal, wenn der Blitzschlagschild zuschlägt, löst sich ein Kugelblitz auf. Auf diese Weise erlischt der Schild nach 10 Min. oder nachdem er 3-mal zugeschlagen hat.\n(Procchance: 50%, 3.5s Abklingzeit)" }
