entries[31772] = { ["name"] = "Speerwurf", ["text"] = "8 - 40 Meter Reichweite\nWirken in 2 sek.\nWirft einen vergifteten Speer auf einen Gegner, fügt körperlichen Schaden und zusätzlich 15 Sek. lang alle 3 Sek. 1 Naturschaden zu." }
