entries[31829] = { ["name"] = "Item - Paladin Pvp Set Retribution 4P Bonus", ["text"] = "Ihr erhaltet eine Aufladung Heiliger Kraft, wenn Ihr direkten Schaden erleidet. Dieser Effekt kann nur einmal alle 8 Sek. auftreten.\n(8s Abklingzeit)" }
