entries[31848] = { ["name"] = "Schild des Templers", ["text"] = "Verringert die Abklingzeit Eurer Fähigkeit 'Zornige Vergeltung' um 20 Sek. und die Abklingzeit Eures Zaubers 'Wächter der Uralten Könige' um 40 Sek. Zudem erzeugt Euer Zauber 'Göttliche Bitte' 1 Heilige Kraft." }
entries[31849] = { ["name"] = "Schild des Templers", ["text"] = "Verringert die Abklingzeit Eurer Fähigkeit 'Zornige Vergeltung' um 40 Sek. und die Abklingzeit Eures Zaubers 'Wächter der Uralten Könige' um 80 Sek. Zudem erzeugt Euer Zauber 'Göttliche Bitte' 2 Heilige Kraft." }
entries[31850] = { ["name"] = "Unermüdlicher Verteidiger", ["text"] = "Sofort 2 min Abklingzeit\nVerringert Euren sämtlichen erlittenen Schaden 8 Sek. lang um 20%.\n\nWährend 'Unermüdlicher Verteidiger' aktiv ist, wird der nächste Angriff, der Euch normalerweise töten würde, Eure Gesundheit stattdessen auf 20% des maximalen Werts setzen." }
entries[31863] = { ["name"] = "Schildansturm", ["text"] = "150 Mana 8 - 25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nStürmt auf einen Gegner zu, fügt 0 Heiligschaden zu und betäubt ihn bis Abbruch lang." }
entries[31865] = { ["name"] = "Verführung", ["text"] = "15 Meter Reichweite\nWirken in 0.5 sek. 6 sek. Abklingzeit\nVerführt 5 Sek. lang in der Nähe befindliche gegnerische Ziele." }
entries[31876] = { ["name"] = "Kommunion", ["text"] = "Eure Auren erhöhen den verursachten Schaden Eurer Gruppen- und Schlachtzugsmitglieder um 3% und Euer verursachter Schaden wird permanent um zusätzlich 2% erhöht. Zudem ruft Euer Zauber 'Richturteil' den Effekt 'Erfrischung' hervor.\n\nErfrischung - Gewährt bis zu 10 Gruppen- oder Schlachtzugsmitgliedern alle 10 Sek. Manaregeneration in Höhe von 1% ihres maximalen Manas. Hält 15 Sek. lang an." }
entries[31884] = { ["name"] = "Zornige Vergeltung", ["text"] = "Sofort 2 min Abklingzeit\nVergeltung\nRuft das Licht an, um zu einem Avatar der Vergeltung zu werden. ['Richturteil' erzeugt zusätzlich 1 Heilige Kraft.][Jede verbrauchte Heilige Kraft lässt Euch in heiliges Licht aufgehen, das Gegnern in der Nähe (13.5% der Angriffskraft) Schaden zufügt.][Verringert die Abklingzeit von 'Heiliger Schock' um 45%.] Erhöht Euren Schaden, Eure Heilung und Eure kritische Trefferchance 20 Sek. lang um 25%.\n\nSchutz\nRuft das Licht an, um zu einem Avatar der Vergeltung zu werden. ['Richturteil' erzeugt zusätzlich 1 Heilige Kraft.][Jede verbrauchte Heilige Kraft lässt Euch in heiliges Licht aufgehen, das Gegnern in der Nähe (13.5% der Angriffskraft) Schaden zufügt.][Verringert die Abklingzeit von 'Heiliger Schock' um 50%.] Erhöht Euren Schaden, Eure Heilung und Eure kritische Trefferchance 20 Sek. lang um 20%.\n\nHeilig\nRuft das Licht an, um zu einem Avatar der Vergeltung zu werden. ['Richturteil' erzeugt zusätzlich 4 Heilige Kraft.][Jede verbrauchte Heilige Kraft lässt Euch in heiliges Licht aufgehen, das Gegnern in der Nähe (13.5% der Angriffskraft) Schaden zufügt.][Verringert die Abklingzeit von 'Heiliger Schock' um 55%.] Erhöht Euren Schaden, Eure Heilung und Eure kritische Trefferchance 20 Sek. lang um 15%." }
